// 快速選擇（三路切分，避免大量重複值退化）
// 平均時間複雜度: O(n)，空間複雜度: O(log n)
function findKthLargest(nums, k) {
    const select = (arr, k) => {
        const pivot = arr[Math.floor(Math.random() * arr.length)];
        const larger = [], equal = [], smaller = [];
        for (const x of arr) {
            if (x > pivot)
                larger.push(x);
            else if (x < pivot)
                smaller.push(x);
            else
                equal.push(x);
        }
        if (k <= larger.length)
            return select(larger, k);
        if (k <= larger.length + equal.length)
            return pivot;
        return select(smaller, k - larger.length - equal.length);
    };
    return select(nums, k);
}

